// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title MessageQueueConsumer
 * @notice Processes messages from an off-chain queue with circuit breaker protection
 * @dev Uses a state machine pattern for circuit breaker with configurable thresholds
 */
contract MessageQueueConsumer {
    enum CircuitState { CLOSED, HALF_OPEN, OPEN }

    struct Message {
        bytes32 id;
        address sender;
        bytes payload;
        uint256 timestamp;
        bool processed;
    }

    struct CircuitBreaker {
        CircuitState state;
        uint256 failureCount;
        uint256 successCount;
        uint256 lastFailureTime;
        uint256 cooldownPeriod;
        uint256 failureThreshold;
        uint256 halfOpenSuccessThreshold;
    }

    mapping(bytes32 => Message) public messageStore;
    mapping(address => bool) public authorizedRelayers;
    CircuitBreaker public breaker;

    address public owner;
    uint256 public nonce;
    bool private _processing;

    // Signal state for async interrupt handling
    uint256 private _signalPending;
    uint256 private _lastSignalBlock;
    mapping(uint256 => bytes32) private _signalQueue;
    uint256 private _signalHead;
    uint256 private _signalTail;

    event MessageProcessed(bytes32 indexed id, bool success);
    event CircuitStateChanged(CircuitState oldState, CircuitState newState);
    event SignalReceived(uint256 indexed signalId, bytes32 messageId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyRelayer() {
        require(authorizedRelayers[msg.sender], "Not authorized relayer");
        _;
    }

    modifier nonReentrant() {
        require(!_processing, "Reentrant call");
        _processing = true;
        _;
        _processing = false;
    }

    constructor(uint256 _cooldown, uint256 _threshold, uint256 _halfOpenThreshold) {
        owner = msg.sender;
        breaker = CircuitBreaker({
            state: CircuitState.CLOSED,
            failureCount: 0,
            successCount: 0,
            lastFailureTime: 0,
            cooldownPeriod: _cooldown,
            failureThreshold: _threshold,
            halfOpenSuccessThreshold: _halfOpenThreshold
        });
    }

    function addRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = true;
    }

    function removeRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = false;
    }

    /**
     * @notice Enqueue a signal interrupt for deferred processing
     * @dev Signals are processed between message batches to handle async events
     */
    function raiseSignal(bytes32 messageId) external onlyRelayer {
        _signalQueue[_signalTail] = messageId;
        _signalTail++;
        _signalPending++;
        _lastSignalBlock = block.number;
        emit SignalReceived(_signalTail - 1, messageId);
    }

    /**
     * @notice Process pending signals - can interrupt message processing
     * @dev This implements the "signal handler" pattern for the queue consumer
     */
    function processSignals() public onlyRelayer {
        while (_signalHead < _signalTail) {
            bytes32 msgId = _signalQueue[_signalHead];
            _signalHead++;
            _signalPending--;

            // Signal handler: attempt to mark message as failed and trip breaker
            if (messageStore[msgId].id != bytes32(0) && !messageStore[msgId].processed) {
                _handleSignalFailure(msgId);
            }
        }
    }

    /**
     * @notice Submit and process a message through the queue
     */
    function consumeMessage(
        bytes32 id,
        bytes calldata payload
    ) external onlyRelayer nonReentrant returns (bool) {
        require(breaker.state != CircuitState.OPEN || _canAttemptReset(), "Circuit is OPEN");

        // Store message
        messageStore[id] = Message({
            id: id,
            sender: msg.sender,
            payload: payload,
            timestamp: block.timestamp,
            processed: false
        });

        // Process any pending signals BEFORE consuming
        // This is the "signal handler" interruption point
        if (_signalPending > 0) {
            processSignals();
        }

        // Check if circuit was tripped by signal processing
        if (breaker.state == CircuitState.OPEN && !_canAttemptReset()) {
            emit MessageProcessed(id, false);
            return false;
        }

        // Execute message processing
        bool success = _executeMessage(id, payload);

        // Update circuit breaker state
        _updateCircuitState(success);

        messageStore[id].processed = true;
        emit MessageProcessed(id, success);
        return success;
    }

    /**
     * @notice Batch consume messages - processes signals between each message
     */
    function batchConsume(
        bytes32[] calldata ids,
        bytes[] calldata payloads
    ) external onlyRelayer nonReentrant {
        require(ids.length == payloads.length, "Length mismatch");
        require(ids.length <= 50, "Batch too large");

        for (uint256 i = 0; i < ids.length; i++) {
            if (breaker.state == CircuitState.OPEN && !_canAttemptReset()) {
                break;
            }

            messageStore[ids[i]] = Message({
                id: ids[i],
                sender: msg.sender,
                payload: payloads[i],
                timestamp: block.timestamp,
                processed: false
            });

            bool success = _executeMessage(ids[i], payloads[i]);
            _updateCircuitState(success);
            messageStore[ids[i]].processed = true;

            emit MessageProcessed(ids[i], success);
        }
    }

    function _handleSignalFailure(bytes32 msgId) internal {
        // Record failure from signal
        breaker.failureCount++;
        breaker.lastFailureTime = block.timestamp;

        if (breaker.failureCount >= breaker.failureThreshold) {
            CircuitState oldState = breaker.state;
            breaker.state = CircuitState.OPEN;
            // Reset success count when opening circuit
            breaker.successCount = 0;
            emit CircuitStateChanged(oldState, CircuitState.OPEN);
        }
    }

    function _executeMessage(bytes32 id, bytes memory payload) internal returns (bool) {
        // Simulate message processing - in production this would call handlers
        if (payload.length < 4) return false;

        bytes4 selector = bytes4(payload[:4]);

        // Basic message validation
        if (selector == bytes4(0xdeadbeef)) return false; // Known bad selector
        if (payload.length > 10000) return false; // Payload too large

        nonce++;
        return true;
    }

    function _updateCircuitState(bool success) internal {
        if (success) {
            if (breaker.state == CircuitState.HALF_OPEN) {
                breaker.successCount++;
                if (breaker.successCount >= breaker.halfOpenSuccessThreshold) {
                    CircuitState oldState = breaker.state;
                    breaker.state = CircuitState.CLOSED;
                    breaker.failureCount = 0;
                    breaker.successCount = 0;
                    emit CircuitStateChanged(oldState, CircuitState.CLOSED);
                }
            } else if (breaker.state == CircuitState.CLOSED) {
                // Decay failure count on success
                if (breaker.failureCount > 0) {
                    breaker.failureCount--;
                }
            }
        } else {
            breaker.failureCount++;
            breaker.lastFailureTime = block.timestamp;
            breaker.successCount = 0;

            if (breaker.failureCount >= breaker.failureThreshold) {
                CircuitState oldState = breaker.state;
                breaker.state = CircuitState.OPEN;
                emit CircuitStateChanged(oldState, CircuitState.OPEN);
            }
        }
    }

    function _canAttemptReset() internal returns (bool) {
        if (block.timestamp >= breaker.lastFailureTime + breaker.cooldownPeriod) {
            CircuitState oldState = breaker.state;
            breaker.state = CircuitState.HALF_OPEN;
            breaker.successCount = 0;
            emit CircuitStateChanged(oldState, CircuitState.HALF_OPEN);
            return true;
        }
        return false;
    }

    function getCircuitState() external view returns (CircuitState) {
        return breaker.state;
    }

    function getPendingSignals() external view returns (uint256) {
        return _signalPending;
    }
}
